def recipe(entry):
    after = entry['before']
    for before, replacement in entry['replacements']:
        assert after.count(before) == 1
        after = after.replace(before, replacement)
    return dict(function=entry['function'], before=entry['before'], after=after)

def generate(entry):
    return json.dumps(recipe(entry), indent=2) + '\n'

